def _version_parts(value):
    """Convert versions like '4.2', 'v4.2.1' into tuples of integers."""
    nums = re.findall(r"\d+", str(value))
    return tuple(int(n) for n in nums) if nums else (0,)


def is_newer_version(remote, local):
    a = list(_version_parts(remote))
    b = list(_version_parts(local))
    length = max(len(a), len(b))
    a += [0] * (length - len(a))
    b += [0] * (length - len(b))
    return tuple(a) > tuple(b)


def mix_hex(a, b, t):
    """Interpolate between two #RRGGBB colors."""
    t = max(0.0, min(1.0, float(t)))
    a = a.lstrip("#")
    b = b.lstrip("#")
    ar, ag, ab = int(a[0:2], 16), int(a[2:4], 16), int(a[4:6], 16)
    br, bg, bb = int(b[0:2], 16), int(b[2:4], 16), int(b[4:6], 16)
    r = round(ar + (br - ar) * t)
    g = round(ag + (bg - ag) * t)
    bl = round(ab + (bb - ab) * t)
    return f"#{r:02x}{g:02x}{bl:02x}"


def ease_out_cubic(t):
    t = max(0.0, min(1.0, float(t)))
    return 1.0 - (1.0 - t) ** 3


def ease_in_out_quint(t):
    t = max(0.0, min(1.0, float(t)))
    return 16 * t**5 if t < 0.5 else 1 - ((-2*t + 2) ** 5) / 2


class RoundButton(tk.Canvas):
    """Premium animated button with hover interpolation + click ripple."""
    def __init__(self, master, text, command=None, width=210, height=48,
                 fill=RED, hover=RED_HOVER, outline=None,
                 font=("Segoe UI Semibold", 10), text_color="white"):
        super().__init__(
            master, width=width, height=height,
            bg=master["bg"], bd=0, highlightthickness=0,
            cursor="hand2"
        )
        self.w = width
        self.h = height
        self.label = text
        self.command = command
        self.fill = fill
        self.hover = hover
        self.outline = outline
        self.font = font
        self.text_color = text_color

        self.hovered = False
        self.disabled = False
        self._hover_value = 0.0
        self._hover_job = None
        self._ripple_items = []

        self._draw()

        self.bind("<Enter>", self._enter)
        self.bind("<Leave>", self._leave)
        self.bind("<Button-1>", self._click)

    def rounded(self, x1, y1, x2, y2, r=14, **kw):
        pts = [
            x1+r, y1, x2-r, y1, x2, y1, x2, y1+r,
            x2, y2-r, x2, y2, x2-r, y2, x1+r, y2,
            x1, y2, x1, y2-r, x1, y1+r, x1, y1
        ]
        return self.create_polygon(
            pts, smooth=True, splinesteps=36, **kw
        )

    def _draw(self):
        self.delete("base")

        if self.disabled:
            main = "#252c37"
            txt = "#6b7687"
        else:
            main = mix_hex(self.fill, self.hover, self._hover_value)
            txt = self.text_color

        # Animated glow for primary red buttons.
        if not self.disabled and self.fill == RED:
            glow_strength = 0.35 + self._hover_value * 0.65
            glow = mix_hex("#140910", "#42101f", glow_strength)
            for i in range(5, 0, -1):
                p = 3 + i * 2
                self.rounded(
                    p, p, self.w-p, self.h-p, 14,
                    fill=glow, outline="", tags="base"
                )

        border = self.outline or (
            mix_hex(BORDER, "#542034", self._hover_value)
            if self.fill != RED else ""
        )

        self.rounded(
            3, 3, self.w-3, self.h-3, 14,
            fill=main, outline=border,
            tags="base"
        )

        # Fine highlight at the top gives the button more depth.
        if not self.disabled:
            shine = mix_hex(main, "#ffffff", 0.08 + self._hover_value * 0.06)
            self.create_line(
                18, 6, self.w-18, 6,
                fill=shine, width=1,
                tags="base"
            )

        self.create_text(
            self.w/2, self.h/2,
            text=self.label,
            fill=txt,
            font=self.font,
            tags="base"
        )

        self.tag_lower("base")

    def _animate_hover(self, target):
        if self._hover_job:
            try:
                self.after_cancel(self._hover_job)
            except Exception:
                pass
            self._hover_job = None

        start = self._hover_value
        frames = 8

        def step(i=0):
            t = ease_out_cubic(i / frames)
            self._hover_value = start + (target - start) * t
            self._draw()

            if i < frames:
                self._hover_job = self.after(14, lambda: step(i + 1))
            else:
                self._hover_value = target
                self._draw()
                self._hover_job = None

        step()

    def _enter(self, _):
        if not self.disabled:
            self.hovered = True
            self._animate_hover(1.0)

    def _leave(self, _):
        self.hovered = False
        self._animate_hover(0.0)

    def _click(self, event):
        if self.disabled:
            return

        # Expanding click ring / ripple.
        x = event.x
        y = event.y
        ripple = self.create_oval(
            x-2, y-2, x+2, y+2,
            outline="#ffffff",
            width=1
        )
        self._ripple_items.append(ripple)

        frames = 9

        def ripple_step(i=0):
            if not self.winfo_exists():
                return
            t = i / frames
            radius = 4 + 40 * ease_out_cubic(t)
            self.coords(
                ripple,
                x-radius, y-radius,
                x+radius, y+radius
            )
            color = mix_hex("#ffffff", self.hover, t)
            self.itemconfigure(ripple, outline=color)

            if i < frames:
                self.after(12, lambda: ripple_step(i + 1))
            else:
                try:
                    self.delete(ripple)
                except Exception:
                    pass

        ripple_step()

        # Tiny press movement without physically shifting the widget.
        old = self._hover_value
        self._hover_value = 1.0
        self._draw()
        self.after(
            75,
            lambda: (
                setattr(self, "_hover_value", old if not self.hovered else 1.0),
                self._draw()
            )
        )

        if self.command:
            self.after(85, self.command)

    def set_text(self, text):
        self.label = text
        self._draw()

    def set_disabled(self, value=True):
        self.disabled = value
        self._draw()


class ModernEntry(tk.Frame):
    def __init__(self, master, placeholder, password=False):
        super().__init__(master, bg=BORDER, height=52)
        self.pack_propagate(False)
        self.placeholder = placeholder
        self.password = password
        self.placeholder_visible = True
        self.revealed = False

        inner = tk.Frame(self, bg="#090e15")
        inner.pack(fill="both", expand=True, padx=1, pady=1)

        self.entry = tk.Entry(
            inner, bg="#090e15", fg=MUTED,
            insertbackground=RED, relief="flat", bd=0,
            font=("Segoe UI", 10)
        )
        self.entry.pack(side="left", fill="both", expand=True, padx=(14, 8), pady=13)
        self.entry.insert(0, placeholder)

        self.eye = None
        if password:
            self.eye = tk.Label(
                inner, text="◉", fg=MUTED, bg="#090e15",
                font=("Segoe UI", 10), cursor="hand2"
            )
            self.eye.pack(side="right", padx=(0, 14))
            self.eye.bind("<Button-1>", self.toggle)

        self.entry.bind("<FocusIn>", self.focus_in)
        self.entry.bind("<FocusOut>", self.focus_out)

    def focus_in(self, _):
        self.configure(bg=RED)
        if self.placeholder_visible:
            self.entry.delete(0, "end")
            self.entry.configure(fg=TEXT)
            self.placeholder_visible = False
            if self.password and not self.revealed:
                self.entry.configure(show="•")

    def focus_out(self, _):
        self.configure(bg=BORDER)
        if not self.entry.get():
            self.entry.configure(show="", fg=MUTED)
            self.entry.insert(0, self.placeholder)
            self.placeholder_visible = True

    def toggle(self, _=None):
        if self.placeholder_visible:
            return
        self.revealed = not self.revealed
        self.entry.configure(show="" if self.revealed else "•")
        if self.eye:
            self.eye.configure(fg=RED if self.revealed else MUTED)

    def set(self, value):
        self.entry.delete(0, "end")
        self.entry.insert(0, value)
        self.entry.configure(fg=TEXT)
        self.placeholder_visible = False
        if self.password and not self.revealed:
            self.entry.configure(show="•")

    def get(self):
        return "" if self.placeholder_visible else self.entry.get()


class Toggle(tk.Canvas):
    def __init__(self, master, value=False, command=None):
        super().__init__(
            master, width=48, height=26, bg=master["bg"],
            highlightthickness=0, bd=0, cursor="hand2"
        )
        self.value = value
        self.command = command
        self.bind("<Button-1>", self.flip)
        self.draw()

    def draw(self):
        self.delete("all")
        fill = RED if self.value else "#29313e"
        self.create_oval(2, 3, 22, 23, fill=fill, outline="")
        self.create_oval(26, 3, 46, 23, fill=fill, outline="")
        self.create_rectangle(12, 3, 36, 23, fill=fill, outline="")
        x = 35 if self.value else 13
        self.create_oval(x-8, 5, x+8, 21, fill="white", outline="")

    def flip(self, _=None):
        self.value = not self.value
        self.draw()
        if self.command:
            self.command(self.value)


class NavButton(tk.Frame):
    """Animated sidebar item: hover fade, selection glow and active pulse."""
    BASE_BG = "#090d13"
    HOVER_BG = "#101620"
    ACTIVE_BG = "#17101a"

    def __init__(self, master, icon, text, command):
        super().__init__(
            master,
            bg=self.BASE_BG,
            height=46,
            cursor="hand2"
        )
        self.pack_propagate(False)

        self.command = command
        self.active = False
        self._hover_value = 0.0
        self._active_value = 0.0
        self._anim_job = None
        self._click_lock = False

        self.bar = tk.Frame(self, bg=self.BASE_BG, width=3)
        self.bar.pack(side="left", fill="y")

        self.icon = tk.Label(
            self,
            text=icon,
            fg=MUTED,
            bg=self.BASE_BG,
            font=("Segoe UI", 10),
            width=3,
            cursor="hand2"
        )
        self.icon.pack(side="left", padx=(9, 0))

        self.label = tk.Label(
            self,
            text=text,
            fg=MUTED,
            bg=self.BASE_BG,
            font=("Segoe UI", 9),
            cursor="hand2"
        )
        self.label.pack(side="left")

        self.dot = tk.Label(
            self,
            text="●",
            fg=self.BASE_BG,
            bg=self.BASE_BG,
            font=("Segoe UI", 7),
            cursor="hand2"
        )
        self.dot.pack(side="right", padx=13)

        for widget in (
            self, self.icon, self.label, self.dot
        ):
            widget.bind("<Button-1>", self._pressed)
            widget.bind("<Enter>", self._enter)
            widget.bind("<Leave>", self._leave)

        self._render_state()

    def _render_state(self):
        # Active value takes precedence over hover value.
        if self.active:
            bg = mix_hex(self.BASE_BG, self.ACTIVE_BG, self._active_value)
            icon_fg = mix_hex(MUTED, RED, self._active_value)
            label_fg = mix_hex(MUTED, TEXT, self._active_value)
            dot_fg = mix_hex(bg, RED, self._active_value)
            bar_fg = mix_hex(bg, RED, self._active_value)
        else:
            bg = mix_hex(self.BASE_BG, self.HOVER_BG, self._hover_value)
            icon_fg = mix_hex(MUTED, TEXT, self._hover_value)
            label_fg = mix_hex(MUTED, TEXT, self._hover_value)
            dot_fg = bg
            bar_fg = bg

        self.configure(bg=bg)
        self.icon.configure(bg=bg, fg=icon_fg)
        self.label.configure(
            bg=bg,
            fg=label_fg,
            font=(
                "Segoe UI Semibold" if self.active else "Segoe UI",
                9
            )
        )
        self.dot.configure(bg=bg, fg=dot_fg)
        self.bar.configure(
            bg=bar_fg,
            width=5 if self.active else 3
        )

    def _animate(self, attr, target, frames=9):
        if self._anim_job:
            try:
                self.after_cancel(self._anim_job)
            except Exception:
                pass
            self._anim_job = None

        start = getattr(self, attr)

        def frame(i=0):
            t = ease_out_cubic(i / frames)
            setattr(self, attr, start + (target - start) * t)
            self._render_state()

            if i < frames:
                self._anim_job = self.after(
                    13, lambda: frame(i + 1)
                )
            else:
                setattr(self, attr, target)
                self._render_state()
                self._anim_job = None

        frame()

    def _enter(self, _):
        if not self.active:
            self._animate("_hover_value", 1.0, 7)

    def _leave(self, _):
        if not self.active:
            self._animate("_hover_value", 0.0, 7)

    def _pressed(self, _):
        if self._click_lock:
            return

        self._click_lock = True

        # Flash selection before the page transition begins.
        previous_active = self._active_value
        self._active_value = 1.0
        self._render_state()

        def finish():
            self._click_lock = False
            if not self.active:
                self._active_value = previous_active
                self._render_state()
            self.command()

        self.after(75, finish)

    def set_active(self, active, animate=True):
        changed = active != self.active
        self.active = active

        if active:
            self._hover_value = 0.0
            if animate and changed:
                self._active_value = 0.0
                self._animate("_active_value", 1.0, 10)
                self.pulse()
            else:
                self._active_value = 1.0
                self._render_state()
        else:
            if animate and changed:
                self._animate("_active_value", 0.0, 7)
            else:
                self._active_value = 0.0
                self._render_state()

    def pulse(self):
        """Short glow pulse when an item becomes selected."""
        def expand(i=0):
            if not self.active:
                return
            widths = [5, 7, 9, 7, 5]
            if i >= len(widths):
                return
            self.bar.configure(width=widths[i])
            self.dot.configure(
                font=("Segoe UI Semibold", 8 if i == 2 else 7)
            )
            self.after(35, lambda: expand(i + 1))

        expand()


class MarikonosV4(tk.Tk):
    def __init__(self):
        super().__init__()
        self.title(APP_NAME)
        self.geometry(f"{WIN_W}x{WIN_H}")
        self.minsize(1060, 650)
        self.configure(bg=BG)
        self.overrideredirect(True)
        self.attributes("-alpha", 0.0)

        self.drag_x = 0
        self.drag_y = 0
        self.fx_enabled = True
        self.always_on_top = False
        self.particles = []
        self.beams = []
        self.squares = []
        self.sparkles = []
        self.wave = 0.0
        self.active_page = "login"
        self.nav = {}

        # Update state
        self.update_prompt_open = False
        self.update_in_progress = False
        self.last_update_status = "Not checked"

        self.logo = tk.PhotoImage(data=LOGO_B64)
        self.logo_big = self.logo.subsample(2, 2)
        self.logo_medium = self.logo.subsample(4, 4)
        self.logo_small = self.logo.subsample(6, 6)

        self.build_shell()
        self.fade_in()

        # Check GitHub shortly after startup without blocking the UI.
        self.after(1800, self.check_for_updates_silent)

    # ========================================================
    # Window / background
    # ========================================================

    def build_shell(self):
        self.fx_canvas = tk.Canvas(self, bg=BG, highlightthickness=0, bd=0)
        self.fx_canvas.place(x=0, y=0, relwidth=1, relheight=1)
        self.build_fx()
        self.animate_fx()

        self.topbar = tk.Frame(self, bg="#070a10", height=45)
        self.topbar.place(x=0, y=0, relwidth=1)
        self.topbar.pack_propagate(False)

        brand = tk.Frame(self.topbar, bg="#070a10")
        brand.pack(side="left", padx=14)

        tk.Label(
            brand, text="◇", fg=RED, bg="#070a10",
            font=("Segoe UI Semibold", 13)
        ).pack(side="left")

        tk.Label(
            brand, text="  MARIKONOS", fg=TEXT, bg="#070a10",
            font=("Segoe UI Semibold", 10)
        ).pack(side="left")

        win_controls = tk.Frame(self.topbar, bg="#070a10")
        win_controls.pack(side="right", padx=10)

        minimize = tk.Label(
            win_controls, text="—", fg=MUTED, bg="#070a10",
            font=("Segoe UI", 12), padx=10, cursor="hand2"
        )
        minimize.pack(side="left")
        minimize.bind("<Button-1>", lambda e: self.minimize())

        close = tk.Label(
            win_controls, text="✕", fg=MUTED, bg="#070a10",
            font=("Segoe UI", 10), padx=10, cursor="hand2"
        )
        close.pack(side="left")
        close.bind("<Button-1>", lambda e: self.destroy())
        close.bind("<Enter>", lambda e: close.configure(fg=RED))
        close.bind("<Leave>", lambda e: close.configure(fg=MUTED))

        for widget in (self.topbar, brand):
            widget.bind("<Button-1>", self.drag_start)
            widget.bind("<B1-Motion>", self.drag_move)

        self.stage = tk.Frame(self, bg=BG)
        self.stage.place(x=0, y=45, relwidth=1, relheight=1, height=-45)

        self.show_login()

    def build_fx(self):
        # Large soft rings / glows
        self.fx_canvas.create_oval(-180, 470, 320, 970, outline="#180d15", width=2)
        self.fx_canvas.create_oval(-130, 520, 270, 920, outline="#111923", width=1)
        self.fx_canvas.create_oval(1010, -170, 1500, 320, outline="#180d15", width=2)

        # Soft glow blobs
        self.fx_canvas.create_oval(-90, -40, 260, 220, fill="#0c1018", outline="")
        self.fx_canvas.create_oval(1030, 560, 1430, 930, fill="#0d1017", outline="")
        self.fx_canvas.create_oval(860, -80, 1270, 250, fill="#120912", outline="")

        # Decorative square / tile style outlines
        tile_specs = [
            (70, 110, 26, "#161d28"), (115, 155, 18, "#23111b"),
            (180, 95, 14, "#17202b"), (1040, 110, 20, "#171f29"),
            (1110, 170, 30, "#24101b"), (1215, 110, 14, "#18212d"),
            (85, 610, 24, "#1a2230"), (150, 670, 16, "#26111c"),
            (1120, 590, 18, "#1a2230"), (1185, 655, 26, "#25111d"),
        ]
        for x, y, s, color in tile_specs:
            self.fx_canvas.create_rectangle(x, y, x+s, y+s, outline=color, width=1)
            self.fx_canvas.create_rectangle(x+5, y+5, x+s-5, y+s-5, outline=color, width=1)

        for _ in range(95):
            x = random.randint(0, WIN_W)
            y = random.randint(0, WIN_H)
            r = random.choice([1, 1, 1, 2])
            speed = random.uniform(0.15, 0.62)
            drift = random.uniform(-0.18, 0.18)
            color = random.choice(["#32111e", "#25111a", "#1b2430", "#222b37", "#2b1130"])
            item = self.fx_canvas.create_oval(
                x-r, y-r, x+r, y+r,
                fill=color, outline=""
            )
            self.particles.append([item, x, y, r, speed, drift])

        # Floating square particles / "carreaux"
        for _ in range(24):
            x = random.randint(0, WIN_W)
            y = random.randint(0, WIN_H)
            size = random.randint(8, 18)
            speed = random.uniform(0.08, 0.28)
            drift = random.uniform(-0.10, 0.10)
            angle = random.uniform(0, math.pi * 2)
            color = random.choice(["#202938", "#29111d", "#18212d"])
            square = self.fx_canvas.create_rectangle(
                x-size, y-size, x+size, y+size,
                outline=color, width=1
            )
            inner = self.fx_canvas.create_rectangle(
                x-size+4, y-size+4, x+size-4, y+size-4,
                outline=color, width=1
            )
            self.squares.append([square, inner, x, y, size, speed, drift, angle])

        # Sparkles / diamond particles
        for _ in range(18):
            x = random.randint(0, WIN_W)
            y = random.randint(0, WIN_H)
            size = random.randint(5, 10)
            speed = random.uniform(0.10, 0.35)
            drift = random.uniform(-0.20, 0.20)
            color = random.choice(["#3b1221", "#1d2734", "#2d1232"])
            diamond = self.fx_canvas.create_polygon(
                x, y-size, x+size, y, x, y+size, x-size, y,
                outline=color, fill="", width=1
            )
            self.sparkles.append([diamond, x, y, size, speed, drift, 0.0])

        for _ in range(8):
            line = self.fx_canvas.create_line(
                0, 0, 0, 0,
                fill="#141b25", width=1
            )
            self.beams.append(line)

    def animate_fx(self):
        self.wave += 0.03
        w = max(self.winfo_width(), WIN_W)
        h = max(self.winfo_height(), WIN_H)

        if self.fx_enabled:
            for p in self.particles:
                item, x, y, r, speed, drift = p
                y -= speed
                x += drift + math.sin(self.wave + y * 0.01) * 0.035
                if y < -10:
                    y = h + 10
                    x = random.randint(0, w)
                if x < -10:
                    x = w + 10
                elif x > w + 10:
                    x = -10
                self.fx_canvas.coords(item, x-r, y-r, x+r, y+r)
                self.fx_canvas.itemconfigure(item, state="normal")
                p[1], p[2] = x, y

            for s in self.squares:
                outer, inner, x, y, size, speed, drift, angle = s
                y -= speed
                x += drift + math.cos(self.wave + angle) * 0.06
                angle += 0.01

                if y < -25:
                    y = h + 25
                    x = random.randint(0, w)
                if x < -25:
                    x = w + 25
                elif x > w + 25:
                    x = -25

                wobble = math.sin(self.wave * 1.3 + x * 0.01) * 2
                self.fx_canvas.coords(outer, x-size, y-size+wobble, x+size, y+size+wobble)
                self.fx_canvas.coords(inner, x-size+4, y-size+4+wobble, x+size-4, y+size-4+wobble)
                self.fx_canvas.itemconfigure(outer, state="normal")
                self.fx_canvas.itemconfigure(inner, state="normal")
                s[2], s[3], s[7] = x, y, angle

            for sp in self.sparkles:
                item, x, y, size, speed, drift, tw = sp
                y -= speed
                x += drift
                tw += 0.12

                if y < -18:
                    y = h + 18
                    x = random.randint(0, w)

                scale = 1.0 + math.sin(tw) * 0.25
                s2 = size * scale
                self.fx_canvas.coords(item, x, y-s2, x+s2, y, x, y+s2, x-s2, y)
                self.fx_canvas.itemconfigure(item, state="normal")
                sp[1], sp[2], sp[6] = x, y, tw

            for i, beam in enumerate(self.beams):
                off = (self.wave * 68 + i * 185) % (w + h)
                self.fx_canvas.coords(beam, off-h, h, off, 0)
                self.fx_canvas.itemconfigure(beam, state="normal")
        else:
            for p in self.particles:
                self.fx_canvas.itemconfigure(p[0], state="hidden")
            for s in self.squares:
                self.fx_canvas.itemconfigure(s[0], state="hidden")
                self.fx_canvas.itemconfigure(s[1], state="hidden")
            for sp in self.sparkles:
                self.fx_canvas.itemconfigure(sp[0], state="hidden")
            for beam in self.beams:
                self.fx_canvas.itemconfigure(beam, state="hidden")

        self.after(30, self.animate_fx)

    def fade_in(self):
        alpha = float(self.attributes("-alpha"))
        if alpha < 0.99:
            self.attributes("-alpha", min(1.0, alpha + 0.045))
            self.after(12, self.fade_in)
        else:
            self.attributes("-alpha", 1.0)

    def drag_start(self, event):
        self.drag_x = event.x
        self.drag_y = event.y

    def drag_move(self, event):
        self.geometry(
            f"+{self.winfo_x() + event.x - self.drag_x}"
            f"+{self.winfo_y() + event.y - self.drag_y}"
        )

    def minimize(self):
        self.overrideredirect(False)
        self.iconify()
        self.bind("<Map>", self.restore_window, add="+")

    def restore_window(self, _=None):
        self.after(20, lambda: self.overrideredirect(True))

