    def clear_stage(self):
        for child in self.stage.winfo_children():
            child.destroy()

    def card(self, parent, bg=PANEL, width=None, height=None):
        frame = tk.Frame(
            parent, bg=bg,
            highlightbackground=BORDER,
            highlightthickness=1
        )
        if width:
            frame.configure(width=width)
        if height:
            frame.configure(height=height)
        return frame

    def title_block(self, parent, title, subtitle):
        tk.Label(
            parent, text=title, fg=TEXT, bg=parent["bg"],
            font=("Segoe UI Semibold", 22)
        ).pack(anchor="w")
        tk.Label(
            parent, text=subtitle, fg=MUTED, bg=parent["bg"],
            font=("Segoe UI", 9)
        ).pack(anchor="w", pady=(3, 0))

    def stat(self, parent, name, value, color):
        c = self.card(parent, height=90)
        c.pack_propagate(False)
        tk.Label(
            c, text=name, fg=MUTED, bg=PANEL,
            font=("Segoe UI Semibold", 7)
        ).pack(anchor="w", padx=14, pady=(14, 4))
        tk.Label(
            c, text=value, fg=color, bg=PANEL,
            font=("Segoe UI Semibold", 11)
        ).pack(anchor="w", padx=14)
        return c

