    def login(self):
        if self.active_page != "login":
            return
        if (
            self.email_entry.get().strip() == LOGIN_EMAIL
            and self.password_entry.get() == LOGIN_PASSWORD
        ):
            self.login_button.set_text("AUTHENTICATING…")
            self.login_button.set_disabled(True)
            self.after(650, self.show_loading)
        else:
            self.shake()
            messagebox.showerror(APP_NAME, "Identifiants incorrects.")

    def shake(self):
        bx, by = self.winfo_x(), self.winfo_y()
        sequence = [10, -10, 8, -8, 5, -5, 2, -2, 0]

        def step(i=0):
            if i >= len(sequence):
                self.geometry(f"+{bx}+{by}")
                return
            self.geometry(f"+{bx + sequence[i]}+{by}")
            self.after(24, lambda: step(i + 1))
        step()

