    def _boot_log(self, message):
        if not hasattr(self, "loading_log"):
            return
        stamp = time.strftime("%H:%M:%S")
        self.loading_log.configure(state="normal")
        self.loading_log.insert("end", f"[{stamp}] {message}\n")
        self.loading_log.see("end")
        self.loading_log.configure(state="disabled")

    def _loading_begin_phase(self, index):
        if self.active_page != "loading":
            return

        if index >= len(self.loading_steps):
            self.after(520, lambda: self.build_app("dashboard"))
            return

        self.loading_phase_index = index
        step = self.loading_steps[index]
        self.loading_target = float(step["target"])

        self.loading_label.configure(text=step["title"])
        self.loading_subtitle.configure(text=step["subtitle"])
        self.loading_phase.configure(text=step["phase"])
        self.loading_tip.configure(text=step["tip"])
        self._boot_log(step["log"])

    def _animate_loading_progress(self):
        if self.active_page != "loading":
            return

        # Smoothly approach the current phase target.
        if self.loading_value < self.loading_target:
            distance = self.loading_target - self.loading_value
            speed = max(0.28, min(1.15, distance * 0.055))
            self.loading_value = min(
                self.loading_target,
                self.loading_value + speed
            )

            pct = int(self.loading_value)
            self.loading_percent_big.configure(text=f"{pct}%")

            # 645 is the canvas progress width.
            px = max(0, min(645, self.loading_value * 6.45))
            glow_x = max(0, px - 34)

            self.progress_canvas.coords(
                self.loading_bar_glow,
                0, 3, px, 15
            )
            self.progress_canvas.coords(
                self.loading_bar,
                0, 5, px, 13
            )
            self.progress_canvas.coords(
                self.loading_head,
                max(0, px - 2), 2,
                min(645, px + 3), 16
            )

        # Move to next phase after reaching target.
        elif self.loading_phase_index < len(self.loading_steps):
            current_index = self.loading_phase_index
            if current_index == len(self.loading_steps) - 1:
                self.loading_phase_index += 1
                self.after(
                    430,
                    lambda: self._loading_begin_phase(
                        len(self.loading_steps)
                    )
                )
            else:
                self.loading_phase_index += 1
                self.after(
                    180,
                    lambda idx=self.loading_phase_index:
                    self._loading_begin_phase(idx)
                )

        self.after(18, self._animate_loading_progress)

    def _animate_loading_visuals(self):
        if self.active_page != "loading":
            return

        self.loading_rotation = (
            self.loading_rotation + 3
        ) % 360
        self.loading_pulse += 0.09
        self.loading_sweep += 1

        # Rotating neon arcs
        self.orbit_canvas.itemconfigure(
            self.loading_arc_1,
            start=self.loading_rotation
        )
        self.orbit_canvas.itemconfigure(
            self.loading_arc_2,
            start=180 - self.loading_rotation * 1.35
        )
        self.orbit_canvas.itemconfigure(
            self.loading_arc_3,
            start=75 + self.loading_rotation * 0.65
        )

        # Pulsating glow
        pulse = (math.sin(self.loading_pulse) + 1.0) / 2.0
        self.orbit_canvas.itemconfigure(
            self.loading_glow_1,
            outline="#471326" if pulse > 0.5 else "#30101d",
            width=2 if pulse > 0.35 else 1
        )
        self.orbit_canvas.itemconfigure(
            self.loading_glow_2,
            outline="#243242" if pulse > 0.5 else "#1a2230"
        )

        # Orbiting nodes
        cx, cy = 127, 127
        radius = 96
        for node, base_angle in self.loading_nodes:
            angle = math.radians(
                base_angle + self.loading_rotation * 1.45
            )
            x = cx + math.cos(angle) * radius
            y = cy + math.sin(angle) * radius
            r = 3.2
            self.orbit_canvas.coords(
                node,
                x-r, y-r, x+r, y+r
            )

        # Background floating diamonds
        w = max(self.winfo_width(), WIN_W)
        h = max(self.winfo_height(), WIN_H)

        for particle in self.loading_particles:
            item, x, y, size, speed, drift = particle
            y -= speed
            x += drift

            if y < -12:
                y = h + 12
                x = random.randint(15, max(16, w - 15))

            wobble = math.sin(
                self.loading_pulse + x * 0.012
            ) * 0.25
            s = size + wobble

            self.boot_canvas.coords(
                item,
                x, y-s,
                x+s, y,
                x, y+s,
                x-s, y
            )
            particle[1], particle[2] = x, y

        # Tile shimmer: only a few tiles at once.
        if self.loading_sweep % 4 == 0 and self.loading_tiles:
            index = (
                self.loading_sweep // 4
            ) % len(self.loading_tiles)

            prev = (index - 1) % len(self.loading_tiles)
            self.boot_canvas.itemconfigure(
                self.loading_tiles[prev],
                outline="#141c27"
            )
            self.boot_canvas.itemconfigure(
                self.loading_tiles[index],
                outline="#441326"
            )

        self.after(24, self._animate_loading_visuals)

