    # ========================================================
    # Safe FiveM cleaner
    # ========================================================

    def five_m_root(self):
        local = os.environ.get("LOCALAPPDATA")
        if not local:
            return None

        candidates = [
            Path(local) / "FiveM" / "FiveM.app",
            Path(local) / "FiveM" / "FiveM Application Data",
            Path(local) / "FiveM",
        ]

        # Prefer the root that looks like the actual FiveM app data folder.
        for candidate in candidates[:2]:
            if candidate.exists():
                return candidate

        # Fallback only if a data folder is directly present.
        fallback = candidates[2]
        if (fallback / "data").exists():
            return fallback

        return candidates[0]

    def clean_targets(self):
        root = self.five_m_root()
        if root is None:
            return []

        return [
            ("FiveM cache", root / "data" / "cache"),
            ("Server cache", root / "data" / "server-cache"),
            ("Private server cache", root / "data" / "server-cache-priv"),
            ("Crash reports", root / "crashes"),
            ("Logs", root / "logs"),
        ]

    def path_size(self, path):
        if not path.exists():
            return 0

        total = 0
        try:
            if path.is_file():
                return path.stat().st_size
            for base, _, files in os.walk(path):
                for name in files:
                    p = Path(base) / name
                    try:
                        total += p.stat().st_size
                    except OSError:
                        pass
        except OSError:
            pass
        return total

    @staticmethod
    def human_size(size):
        units = ["B", "KB", "MB", "GB"]
        value = float(size)
        for unit in units:
            if value < 1024 or unit == units[-1]:
                return f"{value:.1f} {unit}"
            value /= 1024
        return f"{value:.1f} GB"

