    # Auto updater
    # ========================================================

    def _fetch_update_manifest(self):
        """
        Fetch the tiny public version.json file.

        New format supports:
          version
          tag          (optional, defaults to v<version>)
          asset_name   (optional, defaults to marikonos_launcher.exe)
          download_url (optional fallback)
          sha256
          changelog
        """
        request = urllib.request.Request(
            UPDATE_MANIFEST_URL,
            headers={
                "User-Agent": f"{APP_NAME}/{APP_VERSION}",
                "Cache-Control": "no-cache",
            },
        )

        with urllib.request.urlopen(
            request,
            timeout=UPDATE_TIMEOUT
        ) as response:
            raw = response.read().decode("utf-8")

        data = json.loads(raw)

        if not isinstance(data, dict):
            raise ValueError(
                "version.json doit contenir un objet JSON."
            )

        remote_version = str(
            data.get("version", "")
        ).strip()

        if not remote_version:
            raise ValueError(
                "Le champ 'version' manque dans version.json."
            )

        fallback_url = str(
            data.get(
                "download_url",
                data.get("download", "")
            )
        ).strip()

        tag = str(
            data.get("tag", f"v{remote_version}")
        ).strip()

        asset_name = str(
            data.get("asset_name", "")
        ).strip()

        if not asset_name and fallback_url:
            asset_name = Path(
                urllib.parse.urlparse(fallback_url).path
            ).name

        if not asset_name:
            asset_name = DEFAULT_UPDATE_ASSET

        data["version"] = remote_version
        data["tag"] = tag
        data["asset_name"] = asset_name
        data["download_url"] = fallback_url

        return data

    def _github_api_json(self, url):
        """Read public GitHub API JSON without requiring a token."""
        request = urllib.request.Request(
            url,
            headers={
                "User-Agent": f"{APP_NAME}/{APP_VERSION}",
                "Accept": "application/vnd.github+json",
                "X-GitHub-Api-Version": "2022-11-28",
                "Cache-Control": "no-cache",
            },
        )

        with urllib.request.urlopen(
            request,
            timeout=UPDATE_TIMEOUT
        ) as response:
            return json.loads(
                response.read().decode("utf-8")
            )

    def _resolve_update_download_url(self, manifest):
        """
        Resolve the asset from the GitHub release itself.

        This prevents HTTP 404 errors when the executable filename
        changes slightly, because MARIKONOS can find the .exe asset
        from the release instead of trusting only a hard-coded URL.
        """
        remote_version = str(
            manifest.get("version", "")
        ).strip()

        tag = str(
            manifest.get(
                "tag",
                f"v{remote_version}"
            )
        ).strip()

        wanted_asset = str(
            manifest.get(
                "asset_name",
                DEFAULT_UPDATE_ASSET
            )
        ).strip()

        fallback_url = str(
            manifest.get("download_url", "")
        ).strip()

        api_url = (
            f"{GITHUB_API_BASE}/releases/tags/"
            f"{urllib.parse.quote(tag, safe='')}"
        )

        api_error = None

        try:
            release = self._github_api_json(api_url)
            assets = release.get("assets", [])

            if not isinstance(assets, list):
                assets = []

            # 1) exact filename
            for asset in assets:
                if (
                    str(asset.get("name", "")).lower()
                    == wanted_asset.lower()
                ):
                    url = str(
                        asset.get(
                            "browser_download_url",
                            ""
                        )
                    ).strip()

                    if url:
                        manifest[
                            "resolved_asset_name"
                        ] = asset.get("name", wanted_asset)
                        return url

            # 2) prefer any Windows executable if exact name changed
            exe_assets = [
                asset for asset in assets
                if str(
                    asset.get("name", "")
                ).lower().endswith(".exe")
            ]

            if exe_assets:
                asset = exe_assets[0]
                url = str(
                    asset.get(
                        "browser_download_url",
                        ""
                    )
                ).strip()

                if url:
                    manifest[
                        "resolved_asset_name"
                    ] = asset.get("name", "")
                    return url

            # Release exists but there is no .exe attached.
            asset_names = [
                str(asset.get("name", ""))
                for asset in assets
            ]

            raise FileNotFoundError(
                f"La Release {tag} existe, mais aucun fichier .exe "
                f"n'est attaché. Assets trouvés : "
                f"{', '.join(asset_names) or 'aucun'}"
            )

        except urllib.error.HTTPError as exc:
            api_error = exc

            if exc.code == 404:
                api_error = FileNotFoundError(
                    f"La Release GitHub {tag} est introuvable."
                )

        except Exception as exc:
            api_error = exc

        # Fallback for older manifests.
        if fallback_url:
            return fallback_url

        if api_error:
            raise api_error

        raise FileNotFoundError(
            "Impossible de trouver le fichier de mise à jour."
        )

    def check_for_updates_silent(self):
        if self.update_in_progress:
            return
        threading.Thread(
            target=self._check_update_worker,
            args=(False,),
            daemon=True,
        ).start()

    def check_for_updates_manual(self):
        if self.update_in_progress:
            messagebox.showinfo(APP_NAME, "Une mise à jour est déjà en cours.")
            return

        self.last_update_status = "Checking…"
        self._refresh_update_status_label()

        threading.Thread(
            target=self._check_update_worker,
            args=(True,),
            daemon=True,
        ).start()

    def _check_update_worker(self, show_errors):
        try:
            manifest = self._fetch_update_manifest()
            remote = manifest["version"]

            if is_newer_version(remote, APP_VERSION):
                self.last_update_status = f"Update available: {remote}"
                self.after(0, self._refresh_update_status_label)
                self.after(0, lambda: self._offer_update(manifest))
            else:
                self.last_update_status = f"Up to date ({APP_VERSION})"
                self.after(0, self._refresh_update_status_label)
                if show_errors:
                    self.after(
                        0,
                        lambda: messagebox.showinfo(
                            APP_NAME,
                            f"MARIKONOS est déjà à jour.\n\nVersion : {APP_VERSION}",
                        ),
                    )

        except Exception as exc:
            self.last_update_status = "Update check failed"
            self.after(0, self._refresh_update_status_label)

            if show_errors:
                message = str(exc)
                self.after(
                    0,
                    lambda: messagebox.showerror(
                        APP_NAME,
                        "Impossible de vérifier les mises à jour.\n\n"
                        f"{message}\n\n"
                        "Si ton dépôt GitHub est privé, passe-le en Public "
                        "ou utilise un serveur d'update authentifié.",
                    ),
                )

    def _refresh_update_status_label(self):
        label = getattr(self, "update_status_label", None)
        if label is not None and label.winfo_exists():
            label.configure(text=self.last_update_status)

